const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

function makeSimpleHash(text) {
  const str = String(text || '');
  let hash = 0;

  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }

  return Math.abs(hash).toString(16).padStart(8, '0');
}

return items
  .map(item => {
    const title = item.json.title || '';
    const link = item.json.link || '';
    const pub = item.json.isoDate || item.json.pubDate || '';
    const content = item.json.contentSnippet || item.json.content || '';
    const source = item.json.creator || item.json.source || 'google_news';

    const cleanTitle = title.replace(/\s+-\s+[^-]+$/, '').trim();
    const keySource = link || cleanTitle || `${title}-${pub}`;
    const key = makeSimpleHash(keySource) + makeSimpleHash(cleanTitle);

    return {
      json: {
        content_key: key.slice(0, 16),
        source_title: cleanTitle,
        source_link: link,
        source_excerpt: content,
        published_at: pub,
        source,
        source_type: 'news',
        today: now.toISOString(),
        is_recent: !pub || new Date(pub) >= sevenDaysAgo
      }
    };
  })
  .filter(i => i.json.source_title && i.json.source_link && i.json.is_recent);

const incoming = $input.all().map(i => i.json).filter(r =>
  r.source_type === 'news' &&
  r.source_link &&
  r.source_title &&
  r.published_at
);

function similarity(a, b) {
  const sa = new Set(String(a || '').split(/\s+/).filter(Boolean));
  const sb = new Set(String(b || '').split(/\s+/).filter(Boolean));
  const inter = [...sa].filter(x => sb.has(x)).length;
  const union = new Set([...sa, ...sb]).size || 1;
  return inter / union;
}

const blockedKeywords = ['??', '??', '??', '??'];

const seenLinks = new Set();
const keptTitles = [];
const out = [];

for (const art of incoming) {
  const title = String(art.source_title || '').trim();
  const link = String(art.source_link || '').trim();

  if (!title || !link) continue;
  if (blockedKeywords.some(k => title.includes(k))) continue;
  if (seenLinks.has(link)) continue;
  if (keptTitles.some(t => similarity(t, title) >= 0.85)) continue;

  seenLinks.add(link);
  keptTitles.push(title);
  out.push({ json: art });
}

return out.slice(0, 12);

return items.map((item, idx) => {
  const txt = item.json.choices?.[0]?.message?.content || '{}';
  let parsed = {};
  try { parsed = JSON.parse(txt); } catch(e){ parsed = {}; }
  const scoreHint = parsed.score_hint || {};
  const score = Math.round(((scoreHint.click||70)+(scoreHint.save||70)+(scoreHint.debate||70)+(scoreHint.info||70)+(scoreHint.instagram_fit||70))/5);
  const base = $items('Deduplicate + Filter',0)[idx]?.json || {};
  return { json: { ...base, ...parsed, score } };
});

const reels = items.filter(i => (i.json.content_type || 'reel') === 'reel').sort((a,b)=>(b.json.score||0)-(a.json.score||0));
const feeds = items.filter(i => (i.json.content_type || '') === 'feed').sort((a,b)=>(b.json.score||0)-(a.json.score||0));
let chosen = [...reels.slice(0,4)];
if (feeds.length) {
  chosen.push(feeds[0]);
} else if (reels[4]) {
  chosen.push({json:{...reels[4].json, content_type:'feed'}});
}
for (const it of chosen){
  if (!it.json.content_type) it.json.content_type='reel';
}
return chosen;

