const currentSlot = '22:00';

const rows = items.map(i => i.json);

// approved + scheduled_slot 일치 + posted_at 비어있는 것만 바로 찾기
let filtered = rows.filter(r =>
  String(r.approval_status || '').trim().toLowerCase() === 'approved' &&
  String(r.scheduled_slot || '').trim() === currentSlot &&
  !String(r.posted_at || '').trim() &&
  String(r.deleted_at || '').trim() === ''
);

// 같은 content_key가 여러 개면 approved_at / updated_at / row_number 기준으로 최신 것 우선
filtered = filtered.sort((a, b) => {
  const aTime = new Date(a.approved_at || a.updated_at || 0).getTime();
  const bTime = new Date(b.approved_at || b.updated_at || 0).getTime();

  if (bTime !== aTime) return bTime - aTime;
  return (Number(b.row_number) || 0) - (Number(a.row_number) || 0);
});

// content_key 중복 제거
const deduped = [];
const seen = new Set();

for (const r of filtered) {
  const key = String(r.content_key || '').trim();
  if (!key) continue;
  if (seen.has(key)) continue;
  seen.add(key);
  deduped.push(r);
}

let selected = [];

const reel = deduped.find(r => String(r.content_type || '').trim().toLowerCase() === 'reel');
const feed = deduped.find(r => String(r.content_type || '').trim().toLowerCase() === 'feed');

if (reel) selected.push(reel);
if (feed) selected.push(feed);

// reel/feed 없으면 1개라도 내보내기
if (selected.length === 0) {
  selected = deduped.slice(0, 1);
}

return selected.map(r => ({
  json: {
    ...r,
    current_slot: currentSlot,
    selected_at: new Date().toISOString(),
    test_mode: true,
  }
}));

