const raw = $json.choices?.[0]?.message?.content || '{}';

function extractJson(text) {
  const cleaned = String(text || '').trim();
  const f1 = cleaned.match(/```json\s*([\s\S]*?)\s*```/i);
  if (f1) return f1[1].trim();
  const f2 = cleaned.match(/```([\s\S]*?)```/);
  if (f2) return f2[1].trim();
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first !== -1 && last !== -1) return cleaned.slice(first, last + 1);
  return '{}';
}

function normalizeResult(r) {
  const val = String(r || '').toLowerCase();
  if (val.includes('good')) return 'good';
  if (val.includes('bad')) return 'bad';
  return 'bad';
}

let parsed = {};
let fail = false;

try {
  parsed = JSON.parse(extractJson(raw));
} catch {
  fail = true;
}

const fallback =
  String($json.thumbnail_hook || $json.final_title || '').trim();

return [{
  json: {
    hook: String(parsed.hook || fallback).slice(0, 120),
    performance_score: Number(parsed.performance_score || 0),
    result: fail ? 'bad' : normalizeResult(parsed.result),
    reason: fail ? 'parse failed' : String(parsed.reason || '').slice(0, 60),
    logged_at: new Date().toISOString()
  }
}];

