const text = $json.text || '';

// JSON ?? ?? (```json ... ``` ?? { ... } ?? ?? ??)
const jsonMatch = text.match(/```json\s*([\s\S]*?)```/) || 
                  text.match(/(\{[\s\S]*\})/);

if (!jsonMatch) {
  return { json: { title: '', body: '', link: $json.link || '', hashtags: '', safe_image_prompt: '', reel_script: '' } };
}

try {
  const parsed = JSON.parse(jsonMatch[1].trim());
  return { json: {
    title: parsed.title || '',
    body: parsed.body || '',
    link: $json.link || '',
    hashtags: parsed.hashtags || '',
    safe_image_prompt: parsed.safe_image_prompt || '',
    reel_script: parsed.reel_script || ''
  }};
} catch(e) {
  return { json: { title: '', body: '', link: $json.link || '', hashtags: '', safe_image_prompt: '', reel_script: '' } };
}
